&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;figcaption data-lang=&#34;javascript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; parent4 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token literal-property property&#34;&gt;name&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;parent4&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token literal-property property&#34;&gt;path&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;p4&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token function-variable function&#34;&gt;getName&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;name&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;clone1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token parameter&#34;&gt;original&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; clone &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Object&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;create&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;original&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  clone&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function-variable function&#34;&gt;getPath&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; clone&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; child8 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;clone1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;parent4&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;16&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;child8&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;getName&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;17&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;child8&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;getPath&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h2 id=&#34;寄生组合式继承extends关键字做法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#寄生组合式继承extends关键字做法&#34;&gt;#&lt;/a&gt; 寄生组合式继承（extends 关键字做法）&lt;/h2&gt;
&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;figcaption data-lang=&#34;javascript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;clone&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token parameter&#34;&gt;parent&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;child&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  child&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;prototype &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Object&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;create&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;parent&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;prototype&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  child&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;prototype&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;constructor &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; child&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Parent5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;name &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;parent5&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;paly &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token class-name&#34;&gt;Parent5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;prototype&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function-variable function&#34;&gt;getName&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;name&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Child6&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token comment&#34;&gt;// 子类构造函数中调用父类构造函数，组合的方式添加属性&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token function&#34;&gt;Parent5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;call&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;friends &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;child6&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;16&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;17&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// 子类原型是父类原型的实例&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;18&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;clone&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;Parent5&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;Child6&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;19&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token class-name&#34;&gt;Child6&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;prototype&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function-variable function&#34;&gt;getFriends&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;20&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;this&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;friends&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;21&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;22&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; person6 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;Child6&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;23&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;person6&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;24&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;person6&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;getName&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;25&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;person6&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;getFriends&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h1 id=&#34;总结&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#总结&#34;&gt;#&lt;/a&gt; 总结&lt;/h1&gt;
&lt;figure class=&#34;highlight mermaid&#34;&gt;&lt;figcaption data-lang=&#34;mermaid&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;sequenceDiagram&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;	&lt;span class=&#34;token keyword&#34;&gt;Note over&lt;/span&gt; 构造函数继承 &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; 借助call&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;	&lt;span class=&#34;token keyword&#34;&gt;Note over&lt;/span&gt; 原型链继承 &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; 借助prototype&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;	&lt;span class=&#34;token keyword&#34;&gt;Note over&lt;/span&gt; 构造函数继承,原型链继承 &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; 不使用Object.create&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;	&lt;span class=&#34;token keyword&#34;&gt;Note over&lt;/span&gt; 组合继承&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; 构造函数继承 + 原型链继承&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;	&lt;span class=&#34;token keyword&#34;&gt;Note over&lt;/span&gt; 寄生式继承 &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; 使用Object.create&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;	&lt;span class=&#34;token keyword&#34;&gt;Note over&lt;/span&gt; 寄生组合式继承 &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; 寄生式继承 + 组合式继承&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;h1 id=&#34;概念&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#概念&#34;&gt;#&lt;/a&gt; 概念&lt;/h1&gt;
&lt;h3 id=&#34;介绍&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#介绍&#34;&gt;#&lt;/a&gt; 介绍&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;node.js 是一个异步的事件驱动的 &lt;code&gt;JavaScript&lt;/code&gt;  运行时，node.js 的特性其实是 JS 的特性： &lt;code&gt;非阻塞I/O&lt;/code&gt;  和  &lt;code&gt;事件驱动&lt;/code&gt; 。这种基于事件的编程方式具有 &lt;code&gt;轻量级&lt;/code&gt; 、 &lt;code&gt;松耦合&lt;/code&gt; 和 &lt;code&gt;只关注事务点&lt;/code&gt; 等优势。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;发展&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#发展&#34;&gt;#&lt;/a&gt; 发展&lt;/h3&gt;
&lt;p&gt;Node 的出现将前后端的壁垒再次打破，JavaScript 这门最初就能运行在服务端的语言，在经历了前端的辉煌和后端的低迷后，借助事件驱动和 V8 的高性能，再次成为了服务端的佼佼者。在 Web 应用中，JavaScript 将不再仅仅出现在前端浏览器中，因为 Node 的出现，前端将会被重新定义。&lt;/p&gt;
&lt;h3 id=&#34;核心&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#核心&#34;&gt;#&lt;/a&gt; 核心&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 带来的最大特性莫过于：基于事件驱动的非阻塞 I/O 模型，它可以使 CPU 与 I/O 并不相互依赖等待，让资源得到更好的利用&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;架构&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#架构&#34;&gt;#&lt;/a&gt; 架构&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;node 的核心相当于： &lt;code&gt;v8引擎&lt;/code&gt;  +  &lt;code&gt;libuv库&lt;/code&gt;  +  &lt;code&gt;各种native api模块&lt;/code&gt; 的集合&lt;br /&gt;
事件循环&lt;br /&gt;
 node 是利用 v8 引擎打造的基于事件循环实现的异步 I/O 框架&lt;br /&gt;
优势&lt;br /&gt;
 Node 在高并发、高性能后端服务程序上也有着极大的优势：&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;非阻塞 IO 模型（使得 node.js 适用于高交互的场景，可以在等待 IO 操作完成时继续处理其他请求，从而提高性能和吞吐量）&lt;/li&gt;
&lt;li&gt;事件驱动（不创建新的线程的情况下处理大量并发连接，减少了资源消耗并提升了效率）&lt;/li&gt;
&lt;li&gt;单线程（因为 js 运行在单线程上，通过事件循环和回调函数来处理并发，从而避免了多线程编程中的复杂性和同步问题）&lt;/li&gt;
&lt;li&gt;轻量级线程（node.js 使用 libuv 来管理轻量级线程，用于执行实际的 IO 操作）&lt;/li&gt;
&lt;li&gt;跨平台良好&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;认识node&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#认识node&#34;&gt;#&lt;/a&gt; 认识 node&lt;/h1&gt;
&lt;h2 id=&#34;异步io&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#异步io&#34;&gt;#&lt;/a&gt; 异步 IO&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;在 Node 中，绝大多数的操作都是以异步的方式进行调用，这样可以使得操作并行处理，大大节省运行时间。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;单线程&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#单线程&#34;&gt;#&lt;/a&gt; 单线程&lt;/h2&gt;
&lt;p&gt;单线程概念&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;node 单线程指的是：node.js 并没有给我们创建一个线程的能力，所有我们自己写的代码都是单线程执行的，在同一时间内，只能执行我们写的一句代码。但是宿主环境 node.js 并不是单线程的， &lt;code&gt;它会维护一个回调队列&lt;/code&gt; ，libuv 中的线程池在完成一项任务之后 &lt;code&gt;会将回调函数放入回调队列中&lt;/code&gt; ，后面 libuv 会调度 JS 线程来进行执行。因此： &lt;code&gt;单线程操作和并发执行并不冲突，node采用回调队列+事件循环的模式来完成并发操作&lt;/code&gt; &lt;br /&gt;
误区&lt;br /&gt;
除了你的代码是单线程，其余都是多线程（线程池），nodejs 本身是事件驱动，一个 io 事件完成会被放到一个事件队列中，主线程负责轮询这个队列，然后执行相应的回调函数。&lt;br /&gt;
单线程优势&lt;br /&gt;
 node 中：JS 与其余线程是无法共享状态的，单线程最大的优势就在于：不用像多线程那样处处在意同步问题，这里没有死锁的存在，也没有线程上下文交换所带来的性能上的消耗。&lt;br /&gt;
单线程的劣势&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;无法充分利用多核 CPU&lt;/li&gt;
&lt;li&gt;错误会引起整个应用退出&lt;/li&gt;
&lt;li&gt;大量计算占用 CPU 会导致无法继续调用异步 IO&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;跨平台&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#跨平台&#34;&gt;#&lt;/a&gt; 跨平台&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;node.js 的跨平台特性得益于 libuv，和 libuv 的底层屏蔽了各个操作系统之间的差异。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;io密集型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#io密集型&#34;&gt;#&lt;/a&gt; IO 密集型&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;node 很擅长 IO 密集型应用场景，因为 node 面向网络且擅长并行 IO, 能够有效的组织起更多的硬件资源，从而提供更好的服务。IO 密集的优势主要在于 Node 利用事件循环的处理能力，而不是启动每一个线程为每一个请求服务，资源占用极少&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;cpu密集型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#cpu密集型&#34;&gt;#&lt;/a&gt; CPU 密集型&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;由于 v8 引擎的高性能，使得 node.js 在 CPU 密集型应用中仍然有不俗的表现。&lt;br /&gt;
CPU 密集型应用带给 Node.js 最大的挑战是：&lt;br /&gt;
由于 JS 单线程的原因，如果有长时间的运行的计算，将会导致 CPU 时间片不能释放，使得后续 IO 无法发起，但是适当调整和分解大型运算任务为多个小任务就可以使得运算能够适时释放，而不阻塞 IO 调用的发起，这样既可以同时享受到并行异步 IO 的好处又能充分利用 CPU&lt;br /&gt;
node 可以通过编写 C/C++ 扩展的方式更高效的利用 CPU&lt;br /&gt;
node 可以通过子进程的方式将一部分 Node 进程当作常驻服务进行用于计算，然后利用进程间的消息来传递结果，将计算与 IO 分离，这样还能充分利用 CPU&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;分布式应用&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#分布式应用&#34;&gt;#&lt;/a&gt; 分布式应用&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 非常适用于 BFF 中间层，例如：分布式应用，而非单纯的后端开发&lt;br /&gt;
比如一个数据平台去数据库集群中查询数据，node 编写的中间层可以并行的去多台数据库中获取数据并合并，这个过程中，对于 node 来说只是一次普通的 IO 操作，但对于数据库而言是一次复杂的计算，所以也是进而充分压榨硬件资源的过程。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;实时应用&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#实时应用&#34;&gt;#&lt;/a&gt; 实时应用&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;得益于 node 的高性能 IO&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;并行io有效提升web渲染能力&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#并行io有效提升web渲染能力&#34;&gt;#&lt;/a&gt; 并行 IO，有效提升 web 渲染能力&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;摒弃同步等待方式，大胆采用并行 IO，加速数据的获取进而提升 Web 的渲染速度&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模块&#34;&gt;#&lt;/a&gt; 模块&lt;/h1&gt;
&lt;h2 id=&#34;commonjs&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#commonjs&#34;&gt;#&lt;/a&gt; Commonjs&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;Nodejs 采用 Commonjs 的模块规范，在 Node 中，模块分为两类：核心模块和文件模块&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;核心模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#核心模块&#34;&gt;#&lt;/a&gt; 核心模块&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;核心模块部分在 Node 源码编译过程中，编译进了二进制执行文件，在 Node 进行启动时，部分核心模块就被加载进了内存中&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;文件模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#文件模块&#34;&gt;#&lt;/a&gt; 文件模块&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;文件模块则是在运行时动态加载的，需要完整的路径分析、文件定位和编译执行过程，速度比核心模块要慢&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;模块缓存&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模块缓存&#34;&gt;#&lt;/a&gt; 模块缓存&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 像浏览器一样，对于引入过的模块都会进行缓存，浏览器仅仅缓存文件，而 Node 缓存的是编译和执行之后的对象，核心模块的缓存检查先于文件模块的缓存检查&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;文件查找规则&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#文件查找规则&#34;&gt;#&lt;/a&gt; 文件查找规则&lt;/h2&gt;
&lt;h3 id=&#34;路径查找&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路径查找&#34;&gt;#&lt;/a&gt; 路径查找&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;缓存加载&lt;/li&gt;
&lt;li&gt;核心模块，如:fs 模块&lt;/li&gt;
&lt;li&gt;路径形式的文件模块 m&lt;/li&gt;
&lt;li&gt;自定义模块 (node_modules 中)&lt;/li&gt;
&lt;li&gt;
&lt;ul&gt;
&lt;li&gt;自定义模块在查找时，会现在当前文件目录下的 node_modules 目录中向上级依次进行查找，当前文件的路径越深，模块的查找速度就会越慢&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;文件定位&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#文件定位&#34;&gt;#&lt;/a&gt; 文件定位&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;CommonJS 规范允许文件标识符中省略文件后缀，Node 会按照 .js、.json 和.node 的顺序依次补足扩展名，其余扩展名会被当作 js 文件进行载入&lt;/li&gt;
&lt;li&gt;如果查找到是一个文件夹，node 就会查找文件夹中 package.json 的入口文件&lt;/li&gt;
&lt;li&gt;如果还没有找到，Node 就会依次查找 index.js、index.json 和 index.node 文件&lt;/li&gt;
&lt;li&gt;如果还没有找到，node 就会抛出一个异常&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模块全局变量&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模块全局变量&#34;&gt;#&lt;/a&gt; 模块全局变量&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;模块全局变量并不是当 node.js 执行时，声明在全局的，而是类似回调的方式进行的一种首位包装&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模块的编译&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模块的编译&#34;&gt;#&lt;/a&gt; 模块的编译&lt;/h3&gt;
&lt;h4 id=&#34;js模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#js模块&#34;&gt;#&lt;/a&gt; js 模块&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;编译过程中，Node 对获取的 js 文件进行了头尾包装，在头部添加了 (function (exports, require, module, __filename, __dirname) {\n，在尾部添加了 \n});&lt;/li&gt;
&lt;li&gt;有了 exports 还需要 module.exports 的原因在于：避免 exports 直接赋值导致改变了形参的引用&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;cc模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#cc模块&#34;&gt;#&lt;/a&gt; C/C++ 模块&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;对于 C/C++ 模块，Node 调用 process.dlopen () 方法进行加载和执行&lt;/li&gt;
&lt;li&gt;C/C++ 模块主要用于提升执行效率&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;json文件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#json文件&#34;&gt;#&lt;/a&gt; JSON 文件&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;JSON 文件的编译会调用 JSON.parse () 方法得到对象，然后赋值给 exports&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;核心模块-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#核心模块-2&#34;&gt;#&lt;/a&gt; 核心模块&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;核心模块分为 C/C++ 编写的和 JS 编写的两部分&lt;/li&gt;
&lt;li&gt;对于核心模块，Node 采用 V8 附带的工具:js2c.py 工具，将所有内置的 JS 代码转换成 C++ 里面的数组，生成 node_natives.h 头文件&lt;/li&gt;
&lt;li&gt;这个过程中，js 代码以字符串的形式存储在 node 命名空间中，当启动 Node 进行时，js 代码直接加载进内存中，在加载时，js 核心模块经历标识符分析之后直接定位到内存中，比普通文件模块从磁盘中一处一处查找要快很多&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;内建模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#内建模块&#34;&gt;#&lt;/a&gt; 内建模块&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;那些工作在 node 底层、由 C/C++ 编写的模块被称为内建模块&lt;/li&gt;
&lt;li&gt;内建模块的优势在于：首先由于是 C/C++ 编写的，所以性能会优于脚本语言，其次在进行文件编译时，他们被编译为二进制文件，一旦 Node 开始执行，它们就会被加载进内存中，无须再次做标识符定位、文件定位和编译等过程，直接执行即可&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;总结&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#总结&#34;&gt;#&lt;/a&gt; 总结&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;CommonJs 提出的规范均十分简单，但是现实意义却十分强大，node 通过模块规范，组织了自身的原生模块，弥补了 JS 弱结构性的问题，形成了稳定的结构，并向外提供服务&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;异步io-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#异步io-2&#34;&gt;#&lt;/a&gt; 异步 I/O&lt;/h1&gt;
&lt;h2 id=&#34;介绍-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#介绍-2&#34;&gt;#&lt;/a&gt; 介绍&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;与 Node 的事件驱动、异步 I/O 设计理念比较相近的一个知名产品是 Nginx, 它采用 C 编写，性能表现优异，他们的区别在于：Nginx 具备面向客户端管理连接的强大能力，但是它的背后仍然受限于各种同步方式的编程语言，但 Node 却是全方位的，既可以作为服务器端去处理客户端带来的大量并发请求，也可以作为客户端向网络中的各个应用进行并发请求&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;设计理念&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#设计理念&#34;&gt;#&lt;/a&gt; 设计理念&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;为什么需要异步 I/O ?, 原因是 I/O 是昂贵的，而分布式 I/O 是更昂贵的，只有后端能快速响应资源，才能让前端的体验更好&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;资源分配&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#资源分配&#34;&gt;#&lt;/a&gt; 资源分配&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;如果业务场景中有一组互不相关的任务需要完成，目前主流方法有两种:&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;单线程串行依次执行&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;单线程中通常 I/O 与 CPU 计算之间是可以并行进行的，但是同步的编程模型导致的问题是：I/O 的进行会让后续任务等待，造成资源不能更好的去利用&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;多线程并行完成&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;多线程的代价子啊与创建线程和执行期线程上下文切换开销大，并且复杂业务中，多线程编程经常面临锁、状态同步等问题&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;node单线程-多线程&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#node单线程-多线程&#34;&gt;#&lt;/a&gt; Node 单线程 &amp;amp; 多线程&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 单线程是指:js 执行是单线程的，Node 多线程是指：Node 通过 libuv 中多线程队列去接收和响应 I/O 操作。Node 资源分配的方案为：利用单线程执行 js, 远离多线程死锁、状态同步等问题，利用异步 I/O 使得单线程远离阻塞，以便于能够更好的去利用 CPU。为了弥补单线程无法利用多核 CPU 的缺点，Node 提供了子进程，可以通过工作进程高效地利用 CPU 和 I/O&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;异步io与非阻塞io&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#异步io与非阻塞io&#34;&gt;#&lt;/a&gt; 异步 I/O 与非阻塞 I/O&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;操作系统内核对于 I/O 有两种方式：阻塞与非阻塞，在调用阻塞 I/O 时，应用程序需要等待 I/O 完成之后才返回结果。阻塞 I/O 的一个特点就是：调用之后一定要等到系统内核层面完成所有操作之后，调用才结束，系统内核在完成磁盘寻道、读取数据和复制数据到内存中之后，这个调用才结束&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;非阻塞 I/O 和阻塞 I/O 之间的差别在于调用之后是否会立即返回&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;操作系统对计算机进行了抽象，将所有输入输出设备抽象为文件，内核在进行文件 I/O 操作时，通过文件描述符进行管理，而问及教案描述符类似于应用程序和系统内核之间的凭证，应用程序如何需要进行 I/O 调用，需要先打开文件描述符，然后再根据文件描述符去实现文件的数据读写&lt;/li&gt;
&lt;li&gt;非阻塞 I/O 也存在一些问题：由于完整的 I/O 并没有完成，立即返回的并不是业务层期望的数据，而仅仅是当前调用的状态，为了获取完成的数据，应用程序需要重复调用 I/O 操作来确认是否完成，这种重复调用判断操作是否完成的技术叫做轮询&lt;/li&gt;
&lt;li&gt;阻塞 I/O 会造成 CPU 等待的浪费，非阻塞 I/O 带来的麻烦是需要通过轮询去确认是否完全地获取到了数据，会使 CPU 处理状态判断，从而导致 CPU 资源浪费&lt;/li&gt;
&lt;li&gt;经过不断的发展，I/O 事件通知机制现在通常使用 epoll, 它在进入轮询的时候如果没有检查到 I/O 事件，将会进行休眠，指导实践发生将它唤醒，它真实利用了事件通知、执行回调的方式，而不是遍历查询，所以不会浪费 CPU, 执行效率较高，但是休眠期间 CPU 几乎是闲置的&lt;/li&gt;
&lt;li&gt;Node 使用 libuv 中的线程池来完成异步 I/O 的目标，通过让部分线程进行阻塞 I/O 或者非阻塞 I/O 加轮询技术来完成数据获取，让一个线程进行计算处理，通过线程之间的通信，将 I/O 得到的数据进行传递，就轻松实现了异步 I/O。它的思想就是：调用异步方法，等待 I/O 完成之后的通知，执行回调，用户无需考虑轮询，但是它的内部仍然是线程池的原理，不同之处在于这些线程池由系统内核接手管理&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;node的异步io&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#node的异步io&#34;&gt;#&lt;/a&gt; Node 的异步 I/O&lt;/h3&gt;
&lt;h3 id=&#34;事件循环&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#事件循环&#34;&gt;#&lt;/a&gt; 事件循环&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;node 中的事件循环是基于 libuv 的线程池，每一个线程池都有一个 watcher 观察者和一个任务队列，当满足条件时将回调放入任务队列中等待 libuv 调度放入执行栈执行&lt;/li&gt;
&lt;li&gt;事件循环是一个典型的：生产者 / 消费者模型，异步 I/O、网络请求等则是事件的生产者&lt;/li&gt;
&lt;li&gt;进程启动时，Node 便会创建一个类似 while 的循环，每执行一次循环体的过程称为 Tick, 每个 Tick 的过程就是查看是否有事件待处理，如果有就取出事件及相关的回调函数，如果存在关联的回调函数，就执行他们，然后进入下个循环，如果不再有事件处理，就退出进程&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;事件循环流程&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;外部输入数据&lt;/li&gt;
&lt;li&gt;轮询阶段&lt;/li&gt;
&lt;li&gt;check 阶段 (process.nextTick)&lt;/li&gt;
&lt;li&gt;关闭事件回调阶段 (close callback)&lt;/li&gt;
&lt;li&gt;定时器检查阶段 (timer)&lt;/li&gt;
&lt;li&gt;I/O 回调&lt;/li&gt;
&lt;li&gt;闲置阶段 (setImmediate)&lt;/li&gt;
&lt;li&gt;轮询阶段&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;node 中的微任务队列&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;node 中微任务队列有两个:nextTickQueue 和 microTaskQueue&lt;/li&gt;
&lt;li&gt;两个微任务队列的优先级相同，按照代码执行顺序进行执行&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;node 中的宏任务队列&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;timer,setImmediate,I/O 回调等&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;setImmediate 会在当前 tick 执行，而 settimeout 不传参数时，默认很小，可能在当前 tick 被轮询到，也可能当前 tick 没有找到&lt;/p&gt;
&lt;/blockquote&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;setTimeout&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&gt;&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;当前tick执行&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;setImmediate&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&gt;&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;immediate当前tick执行&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;setTimeout&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&gt;&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;下一轮tick执行&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h3 id=&#34;观察者&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#观察者&#34;&gt;#&lt;/a&gt; 观察者&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;每个事件循环中有一个或者多个观察者，而判断是否有事件要处理的过程就是向这些观察者询问是否有要处理的事件&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;请求对象&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#请求对象&#34;&gt;#&lt;/a&gt; 请求对象&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Node 中的异步 I/O 调用而言，回调函数却不由开发者来调用，那么从发出调用之后，到回调函数被执行的过程中，存在一种中间产物，叫做请求对象&lt;/li&gt;
&lt;li&gt;请求对象是异步 I/O 过程中重要的中间产物，所有的状态都保存在这个对象中，包括送入线程池等待执行以及 I/O 操作完毕后的回调处理&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;非io的异步api&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#非io的异步api&#34;&gt;#&lt;/a&gt; 非 I/O 的异步 API&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Node 中还存在一些与 I/O 无关的异步 API, 分别是:setTimeout、setInterval、setImmediate 和 process.nextTick&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;定时器&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;定时器与浏览器中的 API 是一致的，分别用于单次和多次定时执行任务，他们的实现原理与异步 I/O 较为类似，只是不需要 I/O 线程池的参与，调用 setTimeout 或者 setInterval 创建的当时其会被插入到定时器观察者内部的一个红黑树中，每次 Tick 执行时，会从该红黑树中迭代取出定时器对象，检查是否超过定时时间，如果超过就形成一个事件，它的回调函数将会立即执行&lt;/li&gt;
&lt;li&gt;定时器的问题在于不够精确，如果依次循环占用的时间较多，那么下次循环时，也许已经超时了一会&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;process.nextTick&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;每次调用 process.nextTick 时，只会将回调函数放入队列中，在下一轮 Tick 时取出执行&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;setImmediate&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;setImmediate 方法与 process.nextTick 方法十分类似，都是将回调函数延迟执行，但是两者有些细微的差别&lt;/li&gt;
&lt;li&gt;process.nextTick 中的回调函数执行的优先级要高于 setImmediate, 原因是因为事件循环对观察者的检查是有先后顺序的，会先检查 nextTick 的 idle 观察者，后检查 setImmediate 的 check 观察者&lt;/li&gt;
&lt;li&gt;事件循环检查观察者的顺序:idle 观察者 ---I/O 观察者 ---check 观察者&lt;/li&gt;
&lt;li&gt;具体实现上: process.nextTick 的回调函数保存在一个数组中，setImmediate 的结果保存在链表中，在行为上，process.nextTick 在每轮循环中会将数组中的回调函数全部执行完，而 setImmediate 在每轮循环中执行链表中的一个回调函数&lt;/li&gt;
&lt;li&gt;也就是说:setImmediate 的回调在一个 Tick 中只会执行一次&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;事件驱动与高性能服务器&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#事件驱动与高性能服务器&#34;&gt;#&lt;/a&gt; 事件驱动与高性能服务器&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;事件驱动的实质是：通过主循环加事件触发的方式来运行程序&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;服务器模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#服务器模型&#34;&gt;#&lt;/a&gt; 服务器模型&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;同步式，对于同步式的服务，一次只能处理一个请求，并且其余请求都处于等待状态&lt;/li&gt;
&lt;li&gt;每进程 / 每请求，为每个请求启动一个进程，这样可以处理多个请求，但是不具备扩展性，因为系统资源是固定的&lt;/li&gt;
&lt;li&gt;每线程 / 每请求，为每个请求启动一个线程来处理。尽管线程比进程要轻量，但是由于每个线程都占用一定内存，当大并发请求到来时，内存将会很快用光，1 导致服务器缓慢&lt;/li&gt;
&lt;li&gt;Node 通过事件驱动的方式处理请求，无需为每一个请求创建额外的对应先册灰姑娘，可以省略掉创建线程和销毁线程的开销，这是 Node 高性能的一个原因&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;异步回调会被放入到对应的线程中，被相应的观察者进行观察，如果观察者观察到回调需要被执行了，就会放入到相应的任务队列中，从而被事件循环所执行&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;异步编程&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#异步编程&#34;&gt;#&lt;/a&gt; 异步编程&lt;/h1&gt;
&lt;h3 id=&#34;特性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#特性&#34;&gt;#&lt;/a&gt; 特性&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 带来的最大特性莫过于：基于事件驱动的非阻塞 I/O 模型，它可以使 CPU 与 I/O 并不相互依赖等待，让资源得到更好的利用&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;处理异常&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#处理异常&#34;&gt;#&lt;/a&gt; 处理异常&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;尝试对异步方法进行 try/catch 操作只能捕获当次事件循环内的异常，对 callback 执行时抛出的异常将无能为力&lt;/li&gt;
&lt;li&gt;Node 在处理异常上形成了一种约定，江宜常作为回调函数的第一个实参传回，如果为空值则表明异步调用没有异常抛出&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;观察者模式&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#观察者模式&#34;&gt;#&lt;/a&gt; 观察者模式&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;node 中的 event 是一种观察者的设计模式，可以实现一个事件与多个回到函数的关联，这些回调函数又称为事件侦听器.&lt;/li&gt;
&lt;li&gt;观察者模式和发布 / 订阅模式广泛应用于异步编程，通用来解耦业务逻辑&lt;/li&gt;
&lt;li&gt;事件侦听器模式也是一种 Hook 机制，利用钩子导出内部数据或状态给外部的调用者&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;同步 I/O 因为每个 I/O 都是彼此阻塞的，在循环体中，总是一个接着一个的调用，不会耗用文件描述符太多的情况，同时性能也是低下的，对于异步 I/O, 虽然并发容易实现，但是由于太容易实现，依然需要进行控制&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;内存控制&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#内存控制&#34;&gt;#&lt;/a&gt; 内存控制&lt;/h1&gt;
&lt;h3 id=&#34;v8&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#v8&#34;&gt;#&lt;/a&gt; V8&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;在 V8 中，所有的 javaScript 对象都是通过堆来进行分配的&lt;/li&gt;
&lt;li&gt;V8 限制堆大小的原因是因为：V8 最初为浏览器而设计，不太可能遇到用大量内存的场景，而深层原因是因为 V8 垃圾回收机制的限制&lt;/li&gt;
&lt;li&gt;取消 V8 内存限制的方式可以在启动 Node 时传入 --max-old-space-size 或者 --max-new-space-size 来调整内存限制的大小&lt;/li&gt;
&lt;li&gt;V8 垃圾回收机制将内存空间分为新生代和老生代，新生代通过分区、赋值和同一清除的方式销毁旧的数据，老生代通过标记清除法配合清除碎片空间的算法进行清除&lt;/li&gt;
&lt;li&gt;V8 新生代复制和清除的方式只能使用到一半的堆内存，采用的是典型的牺牲空间换取时间的算法，无法大规模的应用到所有的垃圾回收机制中&lt;/li&gt;
&lt;li&gt;垃圾回收是影响性能的因素之一，想要高性能的执行效率就需要注意让垃圾回收尽量少地进行&lt;/li&gt;
&lt;li&gt;node 启动时，添加 --trace_gc 参数就可以查看垃圾回收日志&lt;/li&gt;
&lt;li&gt;node 启动时，添加 --prof 参数就可以得到 V8 执行时地性能分析数据，包含了垃圾回收执行时占用的时间&lt;/li&gt;
&lt;li&gt;V8 中通过 delete 删除对象的属性有可能会干扰到 V8 地优化，所以将属性值赋值为 undefined 或 null 去解引用更好&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 地内存构成主要是通过 V8 进行分配的部分和 Node 自行分配的部分，受 V8 地垃圾回收限制的主要是 V8 的堆内存&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;内存泄漏&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#内存泄漏&#34;&gt;#&lt;/a&gt; 内存泄漏&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Node 对于内存泄漏十分敏感，内存泄露的实质只有一个就是应当回收的对象和出现意外而没有被回收，从而变成了常驻在老生代中的对象&lt;/li&gt;
&lt;li&gt;造成内存泄露的原因主要有几个：缓存、队列消费不及时和作用域未释放&lt;/li&gt;
&lt;li&gt;慎将内存当作缓存，缓存在引用的作用举足轻重，可以十分有效的节省资源，因为它的访问效率要比 I/O 的效率高，一旦命中缓存，就可以节省一次 I/O 的时间&lt;/li&gt;
&lt;li&gt;但是在 Node 中，缓存并不是物美价廉，一旦一个对象被当作缓存来使用，就将会导致垃圾回收机制在机型扫描和整理时，对这些对象做无用功&lt;/li&gt;
&lt;li&gt;在 Node 中，任何试图拿内存当缓存的行为都应该被小心使用&lt;/li&gt;
&lt;li&gt;另一个需要考虑的事情就是：进程之间无法共享内存，如果在进行中使用缓存，这些缓存就不可避免地有重复，对物理内存的使用是一种浪费&lt;/li&gt;
&lt;li&gt;目前使用大量缓存最好的方案是使用进程外的缓存，以减少常驻内存的对象数量，让垃圾回收更高效，并且进程之间可以共享缓存，市面上目前较好的有 Redis&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;内存泄漏排查&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#内存泄漏排查&#34;&gt;#&lt;/a&gt; 内存泄漏排查&lt;/h4&gt;
&lt;p&gt;工具:v8-profiler、node-heapdump 等&lt;/p&gt;
&lt;h3 id=&#34;大内存应用&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#大内存应用&#34;&gt;#&lt;/a&gt; 大内存应用&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;由于 Node 的内存限制，操作大文件时要十分小心，Node 提供了 stream 模块用于处理大文件&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;由于 V8 内存的限制，对于大文件无法通过 fs.readFile 和 fs.writeFile 进行大文件的操作，而是使用 fs.createReadStream 和 fs.createWriteStream 方法通过流的方式对大文件进行操作&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;如果不需要进行字符串层面的操作，则不需要借助 V8 来处理，可以尝试进行纯粹的 Buffer 操作，这将不会受到 V8 堆内存的限制 (不过物理内存仍然有限制)&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;buffer&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#buffer&#34;&gt;#&lt;/a&gt; Buffer&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;Buffer 是一个类似 Array 的对象，但它主要用于操作字节，Buffer 是一个典型的 JavaScript 和 C&lt;ins&gt; 结合的模块，它将性能相关部分用 C&lt;/ins&gt; 实现，将非性能相关的部分用 JavaScript 来实现，Node 中 Buffer 是一个全局对象而无需导入&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;Buffer 占用的内存不是通过 V8 分配的，属于堆外内存&lt;/li&gt;
&lt;li&gt;Buffer 和 Array 类似，可以通过 length 得到长度，也可以通过下标访问元素，也有如 concat 等原型方法，两者的构造方式也相似&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;buffer的转换&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#buffer的转换&#34;&gt;#&lt;/a&gt; Buffer 的转换&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Buffer 对象可以和字符串之间相互进行转换&lt;/li&gt;
&lt;li&gt;字符串转 Buffer:&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;Buffer&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;str&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;encoding&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;ul&gt;
&lt;li&gt;Buffer 转字符串:&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;buf&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;toString&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;encoding&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;start&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;end&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;//buf.toString 默认以 UTF-8 的编码形式&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;ul&gt;
&lt;li&gt;Buffer 不支持某些编码类型，可以通过 Buffer.isEncoding (encoding) 来判断，对于不支持的编码类型可以使用第三方工具库进行转换&lt;/li&gt;
&lt;li&gt;可写流可以通过 setEncoding 设置编码方式&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; rs &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; fs&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;createReadStream&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;test.md&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt; &lt;span class=&#34;token literal-property property&#34;&gt;highWaterMark&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;11&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;rs&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;setEncoding&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;utf8&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h3 id=&#34;buffer与性能&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#buffer与性能&#34;&gt;#&lt;/a&gt; Buffer 与性能&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;Buffer 在文件 I/O 和网络 I/O 中的运用十分广泛，尤其在网络传输中，它的性能举足轻重，一旦在网络中传输，都需要转换为 Buffer, 以进行二进制数据的传输，提高字符串的转换效率，可以很大程度地提高网络的吞吐率&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;通过预先转换静态内容为 Buffer 对象，可以有效减少 CPU 地重复使用，节省服务器资源，静态内容部分可以通过预先转换为 Buffer 的方式，使得性能得到提升&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;网络编程&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网络编程&#34;&gt;#&lt;/a&gt; 网络编程&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;利用 Node 可以十分方便地搭建网络服务器，Node 中提供了 TCP、UDP、HTTP 和 HTTPS 等，适用于服务器端和客户端&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;tcp&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#tcp&#34;&gt;#&lt;/a&gt; TCP&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;TCP 全名传输控制协议，在 OSI 网络模型中属于传输层协议&lt;/li&gt;
&lt;li&gt;TCP 是面向连接的协议，显著特征是在传输之前需要进行三次握手形成会话，只有会话形成之后，服务端和客户端之间才能互相发送数据，在创建会话的过程中，服务端和客户端分别提供一个套接字，两个套接字共同形成一个连接&lt;/li&gt;
&lt;li&gt;在 Node 中通过 net 模块可以创建 TCP 服务&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;tcp服务的事件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#tcp服务的事件&#34;&gt;#&lt;/a&gt; TCP 服务的事件&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;对于通过 net 创建的服务器实例而言，这个实例是一个 EventEmitter 实例，它有几种自定义事件:&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;服务器事件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#服务器事件&#34;&gt;#&lt;/a&gt; 服务器事件&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;listening: 在调用 server.listen 绑定端口后触发&lt;/li&gt;
&lt;li&gt;connection: 每个客户端套接字连接到服务端时触发，简洁写法为通过 net.create-Server, 最后一个参数传递&lt;/li&gt;
&lt;li&gt;close: 当服务器关闭时触发，在调用 server.close 之后，服务器将停止接收进的套接字连接&lt;/li&gt;
&lt;li&gt;error: 当服务器异常时，会触发该事件&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;连接事件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#连接事件&#34;&gt;#&lt;/a&gt; 连接事件&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;data: 当一端调用 write 发送数据时，另一端会触发 data 事件，事件传递的数据是 write 发送的数据&lt;/li&gt;
&lt;li&gt;end: 当连接中的任意一端发送了 FIN 数据时，将会触发该事件&lt;/li&gt;
&lt;li&gt;drain: 当任意一端调用 write 发送数据时，当前这端会触发该事件&lt;/li&gt;
&lt;li&gt;等等&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;udp服务&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#udp服务&#34;&gt;#&lt;/a&gt; UDP 服务&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;UDP 又称用户数据包协议，与 TCP 一样属于网络传输层，UDP 与 TCP 最大的不同就在于：UDP 不是面向连接的，TCP 中连接一旦建立，所有的会话都基于连接完成，客户端如果要与另一个 TCP 服务通信，需要再创建一个套接字来完成连接，但是在 UDP 中，一个套接字可以与多个 UDP 服务通信&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;要在 Node.js 中创建 UDP 服务器端，需要调用 dgram 模块&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;http模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#http模块&#34;&gt;#&lt;/a&gt; HTTP 模块&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 的 HTTP 模块包含对 HTTP 处理的封装，在 Node 中 HTTP 服务器继承自 TCP 服务器 (net 模块), 他可以与多个客户端保持连接，由于其采用事件驱动的形式，并不会为每一个连接创建额外的线程或者进程，保持很低的内存占用，所以能实现高并发&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;开启 keepalive 之后，一个 TCP 会话可以用于多次请求和响应&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;http服务的事件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#http服务的事件&#34;&gt;#&lt;/a&gt; HTTP 服务的事件&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;服务器也是一个 EventEmitter 实例，具有以下事件:&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;connection 事件：这个连接可能因为开启了 keep-alive, 可以在多次请求响应之间使用，当这个连接建立时，服务器触发一次 connection 事件&lt;/li&gt;
&lt;li&gt;request 事件：解析出 HTTP 请求头之后，将会触发该事件，在 res.end 之后，TCP 连接可能将用于下一次请求响应&lt;/li&gt;
&lt;li&gt;close 事件：与 TCP 服务器行为一致，调用 server.close 方法传递一个回调函数来快速注册该事件&lt;/li&gt;
&lt;li&gt;checkContinue 事件和 connect 事件等&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;websocket服务&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#websocket服务&#34;&gt;#&lt;/a&gt; WebSocket 服务&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;WebSocket 实现了客户端与服务器端之间的长连接，而 Node 事件驱动的方式十分擅长与大量的客户端保持高并发连接&lt;/li&gt;
&lt;li&gt;相比于 HTTP,WebSocket 更接近于传输层协议，它并没有在 HTTP 的基础上模拟服务器端的推送，而是在 TCP 上定义独立地协议&lt;/li&gt;
&lt;li&gt;WebSokcet 协议主要分为两个部分：握手和传输数据&lt;/li&gt;
&lt;li&gt;客户端将会校验 Sec-WebSocket-Accept 的值，如果成功将会开始接下来的数据传输&lt;/li&gt;
&lt;li&gt;为了安全考虑，客户端需要对发送的数据帧进行掩码处理，服务器一旦收到无掩码帧 (比如中间拦截破坏), 连接就会关闭&lt;/li&gt;
&lt;li&gt;基于事件驱动的方式使得 Node 对于 WebSocket 这类长连接的应用场景可以轻松地处理大量并发请求&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;网络服务与安全&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网络服务与安全&#34;&gt;#&lt;/a&gt; 网络服务与安全&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;SSL: 安全套接层 SSL 作为一种安全协议，他在传输层提供了对网络连接加密的功能，对于应用层而言，它是透明的，最初的 SSL 应用在 Web 上，被服务端和浏览器端同时支持，随后被标准化为 TLS (安全传输层协议)&lt;/li&gt;
&lt;li&gt;Node 在网络安全上提供了 3 个模块:crypto、tls 和 https, 其中 crypto 主要用于加密解密，真正用于网络的是 tls 模块和 https 模块&lt;/li&gt;
&lt;/ul&gt;
&lt;h6 id=&#34;tlsssl&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#tlsssl&#34;&gt;#&lt;/a&gt; TLS/SSL&lt;/h6&gt;
&lt;blockquote&gt;
&lt;p&gt;TLS 和 SSL 是一个公钥 / 私钥的结构，他是一个非对称的结构，每个服务器端和客户端都有自己的公钥和私钥，公钥用于加密要传输的数据，私钥用于解密接收到的数据&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;公私钥的非对称加密性虽好，但是网络中依然可能存在窃听的情况，比如：中间人攻击&lt;/li&gt;
&lt;li&gt;为了解决这个问题，TLS/SSL 引入了数字证书来进行认证&lt;/li&gt;
&lt;li&gt;CA (数字证书认证中心) 的作用就是为站点颁发证书&lt;/li&gt;
&lt;li&gt;通过 CA 机构颁发证书通常是一个繁琐的过程，需要付出一定的精力和费用，服务器端需要向 CA 机构进行申请&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;中间件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#中间件&#34;&gt;#&lt;/a&gt; 中间件&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;中间件的作用是用于简化和隔离基础设施与业务逻辑之间的细节，让开发者能够关注在业务的开发上，以达到提升开发效率的目的&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;中间件的意义在于：封装了底层细节，为上层提供更方便的服务&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;node多进程&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#node多进程&#34;&gt;#&lt;/a&gt; Node 多进程&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;如何充分利用多核 CPU 一直是服务端关心和探讨的话题之一。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;child_process&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#child_process&#34;&gt;#&lt;/a&gt; child_process&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;spawn: 启动一个子进程来执行命令&lt;/li&gt;
&lt;li&gt;exec: 启动一个子进行执行命令，他有一个回调函数获知子进程的状况&lt;/li&gt;
&lt;li&gt;execFile: 启动子进程执行可执行文件&lt;/li&gt;
&lt;li&gt;fork:fork 创建的 Node 子进程只需要指定要执行的 JavaScript 文件模块即可&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;cluster模块&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#cluster模块&#34;&gt;#&lt;/a&gt; Cluster 模块&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;为了创建单机 Node 集群，只使用 child_process 的话有许多细节需要进行处理&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;原理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#原理&#34;&gt;#&lt;/a&gt; 原理&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;cluster 模块就是 child_process 和 net 模块的组合应用，当 cluster 启动时，他会在内部启动 TCP 服务器，当 cluster.fork 子进程时，会将这个 TCP 服务器端 socket 的文件描述符发送给工作进程，如果进程是通过 cluster.fork 复制出来的，那么它的环境变量中就存在 NODE_UNIQUE_ID, 如果工作进程中存在 listen 侦听网络端口的调用，它将拿到文件描述符，通过端口重用实现多个子进程共享端口&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;进程间通信&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#进程间通信&#34;&gt;#&lt;/a&gt; 进程间通信&lt;/h3&gt;
&lt;h5 id=&#34;浏览器端&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#浏览器端&#34;&gt;#&lt;/a&gt; 浏览器端&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;浏览器端 WebWorker 允许创建工作线程并在后台运行，使得一些阻塞较为严重的计算不会影响主线程上的 UI 渲染&lt;/li&gt;
&lt;li&gt;主线程通过 onmessage 和 postMessage 进行发送和接收数据，子进程对象通过 send 发送数据，通过 message 事件接收数据&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;进程间通信原理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#进程间通信原理&#34;&gt;#&lt;/a&gt; 进程间通信原理&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;IPC 全称为进程间通信，进程间通信的目的是为了让不同的进程能够互相访问资源并进行协调工作&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;实现进程间通信的技术&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#实现进程间通信的技术&#34;&gt;#&lt;/a&gt; 实现进程间通信的技术&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;命名管道、匿名管道 (文件描述符)&lt;/li&gt;
&lt;li&gt;socket (通用通信接口)&lt;/li&gt;
&lt;li&gt;信号量 (进程间通过发布订阅的模式监听事件)&lt;/li&gt;
&lt;li&gt;共享内存 (映射同一内存地址)&lt;/li&gt;
&lt;li&gt;消息队列等等 (一个进程创建消息队列，另一个进程向其消息队列发送消息)&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 中实现 IPC 通道的是管道技术，这种技术很适合父子进程之间的状态通信&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;node中ipc通道&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#node中ipc通道&#34;&gt;#&lt;/a&gt; Node 中 IPC 通道&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;Node 中父进程在创建子进程之前，会创建 IPC 通道并监听它，然后才真正创建出子进程，并通过环境变量告诉子进程这个 IPC 通道的文件描述符&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;后端技术方案&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#后端技术方案&#34;&gt;#&lt;/a&gt; 后端技术方案&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;为了解决性能问题和 Session 数据无法跨进程共享的问题，常常将 Session 集中化，将原本可能分散在多个进程里的数据，同意转移到集中的数据存储中，目前常用的工具是 Redis、Memcached 等，通过这些高效的缓存，Node 进程无须在内部维护数据对象，垃圾回收问题和内存限制问题都可以迎刃而解，并且这些高速缓存设计的缓存过期策略更加合理更加高效，比在 Node 中自定设计缓存策略更好&lt;/li&gt;
&lt;/ul&gt;

 &lt;h1 id=&#34;前端网络安全&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#前端网络安全&#34;&gt;#&lt;/a&gt; 前端网络安全&lt;/h1&gt;
&lt;h2 id=&#34;xss跨站脚本攻击&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#xss跨站脚本攻击&#34;&gt;#&lt;/a&gt; XSS 跨站脚本攻击&lt;/h2&gt;
&lt;h4 id=&#34;介绍&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#介绍&#34;&gt;#&lt;/a&gt; 介绍&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;XSS 跨站脚本攻击侧重于脚本，旨在千方百计地注入并执行恶意的脚本代码&lt;/li&gt;
&lt;li&gt;XSS 常用于通过 url 参数的形式或者输入框中输入脚本的形式进行攻击，分为反射性、储存型和 DOM 型。&lt;/li&gt;
&lt;li&gt;反射性：主要是攻击者浏览器提交恶意代码到服务端，服务端将恶意代码传回到客户端&lt;/li&gt;
&lt;li&gt;存储型：攻击者提交恶意代码到服务器，服务器将恶意代码存储到数据库&lt;/li&gt;
&lt;li&gt;DOM 型：攻击者提交 DOM 操作脚本显示广告等。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;预防&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#预防&#34;&gt;#&lt;/a&gt; 预防&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;将 &amp;quot;&amp;lt;&amp;quot;、&amp;quot;&amp;gt;&amp;quot; 等脚本符号替换为转义字符&lt;/li&gt;
&lt;li&gt;插入无意义的 ansi 转义码&lt;/li&gt;
&lt;li&gt;过滤 script 标签&lt;/li&gt;
&lt;li&gt;进行格式校验，提交阶段防止&lt;/li&gt;
&lt;li&gt;限制输出长度增加攻击难度&lt;/li&gt;
&lt;li&gt;服务端 cookie 设置 http only 属性&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;csrf跨站请求伪造&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#csrf跨站请求伪造&#34;&gt;#&lt;/a&gt; CSRF 跨站请求伪造&lt;/h2&gt;
&lt;h4 id=&#34;介绍-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#介绍-2&#34;&gt;#&lt;/a&gt; 介绍&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;CSRF 侧重于诱导用户操作的方式来借用用户的名义干坏事。&lt;/li&gt;
&lt;li&gt;通常在不知名网站中嵌入不可见的 iframe 或者 a 标签，诱导用户点击&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;预防-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#预防-2&#34;&gt;#&lt;/a&gt; 预防&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;重要的请求操作使用强制验证，比如手机号或邮箱验证&lt;/li&gt;
&lt;li&gt;服务器端阻止第三方网站请求接口&lt;/li&gt;
&lt;li&gt;严格控制 get 请求的幂等性，不让 get 请求修改到数据。&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;详解&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#详解&#34;&gt;#&lt;/a&gt; 详解&lt;/h1&gt;
&lt;h2 id=&#34;&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#&#34;&gt;#&lt;/a&gt; &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96eHBzdXBlci5naXRodWIuaW8vYWR2YW5jZWRfZnJvbnRfZW5kL2Jvb2svYnJvd3Nlci9zYWZlLmh0bWwjXzEteHNzLSVFOCVCNyVBOCVFNyVBQiU5OSVFOCU4NCU5QSVFNiU5QyVBQyVFNiU5NCVCQiVFNSU4NyVCQg==&#34;&gt;#&lt;/span&gt;1. XSS 跨站脚本攻击&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;原理&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;XSS 是常见的 Web 攻击技术之一。所谓的跨站脚本攻击指的是：恶意攻击者往 Web 页面里注入恶意 Script 代码，用户浏览这些网页时，就会执行其中的恶意代码，可对用户进行盗取 cookie 信息、会话劫持等各种攻击。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;危害&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;1、&lt;strong&gt;盗取各类用户帐号&lt;/strong&gt;，如机器登录帐号、用户网银帐号、各类管理员帐号&lt;/p&gt;
&lt;p&gt;2、&lt;strong&gt;控制企业数据&lt;/strong&gt;，包括读取、篡改、添加、删除企业敏感数据的能力&lt;/p&gt;
&lt;p&gt;3、&lt;strong&gt;盗窃企业重要的具有商业价值的资料&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;4、&lt;strong&gt;非法转账&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;5、&lt;strong&gt;强制发送电子邮件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;6、&lt;strong&gt;网站挂马&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;7、&lt;strong&gt;控制受害者机器向其它网站发起攻击&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;前端如何处理&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;过滤用户的输入信息，禁止用户在输入的过程中输入 &amp;quot;&amp;lt;&amp;quot;, &amp;quot;&amp;gt;&amp;quot;, &amp;quot;引号&amp;quot;, &amp;quot;$&amp;quot;, &amp;quot;_&amp;quot;&lt;/li&gt;
&lt;li&gt;核心的用户身份标示或 token 保存在 Cookie 中，Cookie 中一定要加 “HTTPOnly” 在结尾，保证只有在 html 操作时才能将 cookie 中的内容发送出去，在 JS 中无法获得用户的 Cookie 信息&lt;/li&gt;
&lt;li&gt;限制输入的内容长度，增大攻击难度&lt;/li&gt;
&lt;li&gt;使用 ansi 转义码，增加无意义的转义序列&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#-2&#34;&gt;#&lt;/a&gt; &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96eHBzdXBlci5naXRodWIuaW8vYWR2YW5jZWRfZnJvbnRfZW5kL2Jvb2svYnJvd3Nlci9zYWZlLmh0bWwjXzItY3NyZi0lRTclQkQlOTElRTclQkIlOUMlRTYlOTQlQkIlRTUlODclQkI=&#34;&gt;#&lt;/span&gt;2. CSRF 网络攻击&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;原理&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;CSRF（Cross-site request forgery）跨站请求伪造，也被称为 “One Click Attack” 或者 Session Riding，通常缩写为 CSRF，是一种对网站的恶意利用。尽管听起来像跨站脚本（XSS），但它与 XSS 非常不同，XSS 利用站点内的信任用户，而 CSRF 则通过伪装来自受信任用户的请求来利用受信任的网站。与 XSS 攻击相比，CSRF 攻击往往不大流行（因此对其进行防范的资源也相当稀少）和难以防范，所以被认为比 XSS 更具危险性。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;前端如何处理&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;减少在 cookie 中存储客户核心内容比如用户的 token、ID、access_token 等&lt;/li&gt;
&lt;li&gt;GET 请求不对数据进行修改&lt;/li&gt;
&lt;li&gt;不让第三方网站访问到 Cookie&lt;/li&gt;
&lt;li&gt;阻止第三方网站请求接口&lt;/li&gt;
&lt;li&gt;请求时附带验证信息，比如验证码或者 Token&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;-3&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#-3&#34;&gt;#&lt;/a&gt; &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96eHBzdXBlci5naXRodWIuaW8vYWR2YW5jZWRfZnJvbnRfZW5kL2Jvb2svYnJvd3Nlci9zYWZlLmh0bWwjXzMtZGRvcy0lRTYlOTQlQkIlRTUlODclQkI=&#34;&gt;#&lt;/span&gt;3. DDOS 攻击&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;原理&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;DDOS 攻击，它在短时间内发起大量请求，耗尽服务器的资源，无法响应正常的访问，造成网站实质下线。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;前端如何处理&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;防范 DDOS 的第一步，就是你要有一个备份网站，或者最低限度有一个临时主页。生产服务器万一下线了，可以立刻切换到备份网站，不至于毫无办法。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;后端如何处理&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;建立 IP 黑名单，阻断已知的攻击源&lt;/li&gt;
&lt;li&gt;HTTP 请求的拦截，恶意请求都是从某个 IP 段发出的，那么把这个 IP 段封掉就行了。或者，它们的 User Agent 字段有特征（包含某个特定的词语），那就把带有这个词语的请求拦截。&lt;/li&gt;
&lt;li&gt;网络带宽扩容，或者使用 CDN&lt;/li&gt;
&lt;/ul&gt;

 &lt;p&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9naXRodWIuY29tL2NoZW56b21pMTIvRGVlcExlYXJuaW5nU3lzdGVt&#34;&gt;资料链接&lt;/span&gt;&lt;/p&gt;
&lt;h1 id=&#34;编译方式&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#编译方式&#34;&gt;#&lt;/a&gt; 编译方式&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;静态编译 AOT：静态编译需要通过编译器将源代码编译为机器码，以便于在目标平台上直接使用。&lt;/li&gt;
&lt;li&gt;动态解释 JIT：动态解释需要通过解释器一边解释编译一边执行。&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;编译器与解析器&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#编译器与解析器&#34;&gt;#&lt;/a&gt; 编译器与解析器&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/%E7%BC%96%E8%AF%91%E5%99%A8%E4%B8%8E%E8%A7%A3%E6%9E%90%E5%99%A8.png&#34; alt=&#34;编译器与解析器&#34; /&gt;&lt;/p&gt;
&lt;h1 id=&#34;jit和aot&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#jit和aot&#34;&gt;#&lt;/a&gt; JIT 和 AOT&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/JIT%E5%92%8CAOT.png&#34; alt=&#34;JTI和AOT&#34; /&gt;&lt;/p&gt;
&lt;h1 id=&#34;pass扫描&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#pass扫描&#34;&gt;#&lt;/a&gt; Pass 扫描&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/Pass.png&#34; alt=&#34;Pass&#34; /&gt;&lt;/p&gt;
&lt;h1 id=&#34;ir&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ir&#34;&gt;#&lt;/a&gt; IR&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/IR.png&#34; alt=&#34;IR&#34; /&gt;&lt;/p&gt;
&lt;h1 id=&#34;编译器的基本构成&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#编译器的基本构成&#34;&gt;#&lt;/a&gt; 编译器的基本构成&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;Source Code 原代码 ---- Front-End 编译前端 ---- Optimizer 中间代码优化 ---- Back-End 编译后端 ---- Machine Code 机器码&lt;/li&gt;
&lt;li&gt;Front-End：编译器前端，主要用于对源程序进行一些转化，负责：词法分析、语法分析、将原代码转化为抽象语法树&lt;/li&gt;
&lt;li&gt;Optimizer：中间优化，基于语法树进行 IR 优化，使得代码更加高效，包括剔除 dead code 等&lt;/li&gt;
&lt;li&gt;Back-End：编译器后端，通过语法树语义分析生成机对应硬件的器码&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;编译器的历史&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#编译器的历史&#34;&gt;#&lt;/a&gt; 编译器的历史&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;最早的编译器是 gcc，可以支持跨平台交叉编译、并且支持多种语言如：C、C++、Java 等&lt;/li&gt;
&lt;li&gt;不过 gcc 的扩展性很差，仓库体积庞大不利于作为工具被扩展，编译出来的机器码耦合严重，于是就有了 llvm&lt;/li&gt;
&lt;li&gt;llvm 通过 IR 将高级语言和不同的机器码语法之间的差异进行屏蔽，假设要增加支持一个新的硬件的机器码，只需要改硬件对接 IR 即可&lt;/li&gt;
&lt;li&gt;还有一个比较核心的概念就是 llvm 库的概念，llvm 是一个工具集合，这使得它可以被很好的被扩展使用&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;llvm-ir&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#llvm-ir&#34;&gt;#&lt;/a&gt; LLVM IR&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/LLVM-IR.png&#34; alt=&#34;LLVM-IR&#34; /&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;LLVM IR 作为一种编译器 IR，它的两个基本原则指导着整个核心库的开发：&lt;/li&gt;
&lt;li&gt;1、SSA（静态单赋值）的方式表示，代码组织为三地址指令序列和无限寄存器让优化能够快速执行，两个重要特征为：代码组织为三地址指令序列、寄存器数量没有限制。&lt;/li&gt;
&lt;li&gt;2、整个程序的 IR 存储到磁盘让链接时优化易于实现&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;ssa静态单赋值&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ssa静态单赋值&#34;&gt;#&lt;/a&gt; SSA 静态单赋值&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/SSA.png&#34; alt=&#34;SSA静态单赋值&#34; /&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;SSA 静态单赋值是 LLVM-IR 中间表示的一个重要特性，它使得每个值只有单一赋值定义了它，每次使用一个值，可以立即向后追溯其定义的唯一指令，是用于代码优化的产物。&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;三地址码&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#三地址码&#34;&gt;#&lt;/a&gt; 三地址码&lt;/h1&gt;
&lt;p&gt;&lt;img data-src=&#34;/images/%E4%B8%89%E5%9C%B0%E5%9D%80%E7%A0%81.png&#34; alt=&#34;三地址码&#34; /&gt;&lt;/p&gt;
&lt;h1 id=&#34;ai编译器&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ai编译器&#34;&gt;#&lt;/a&gt; AI 编译器&lt;/h1&gt;

 &lt;h1 id=&#34;概念&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#概念&#34;&gt;#&lt;/a&gt; 概念&lt;/h1&gt;
&lt;h2 id=&#34;互联网internet&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#互联网internet&#34;&gt;#&lt;/a&gt; 互联网 Internet&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;互联网是一个全球性的网络，由无数个私人网、公共网、学术网和政府网所组成，这些网络通过一系列标准的协议和技术服务相互连接，互联网的核心包括：全球性、开放性、互联性和服务多样性。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;广域网wan&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#广域网wan&#34;&gt;#&lt;/a&gt; 广域网 WAN&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;广域网是一种覆盖地理区域的计算机网络，通常跨越多个城市、州或国家。广域网&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;ppp链路&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ppp链路&#34;&gt;#&lt;/a&gt; PPP 链路&lt;/h5&gt;
&lt;p&gt;广域网在数据链路层通过 PPP 协议来传输数据。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;PPP 点对点协议&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;路由器&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路由器&#34;&gt;#&lt;/a&gt; 路由器&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;路由器又称为网关&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;一台路由器对应多个网卡&lt;/li&gt;
&lt;li&gt;路由器可以拥有多个 IP 地址，常见有内部 IP 地址、外部 IP 地址和其他 IP 地址。&lt;/li&gt;
&lt;li&gt;路由器还可以支持网络地址转换（NAT 协议），可以将局域网划分为多个独立的子网，每个子网都有自己的 IP 地址范围。&lt;/li&gt;
&lt;li&gt;路由器 WAN 口 IP 是 ISP 提供的 IP 地址，可能由 ISP 动态分配，也可能是静态分配的，用于路由器与互联网之间的通信。&lt;/li&gt;
&lt;li&gt;路由器 LAN 口 IP 是路由器为其管理的局域网分配的 IP 地址，每一个 LAN 口对应一个端口号，用于设备与路由器之间通信。&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;ip地址&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ip地址&#34;&gt;#&lt;/a&gt; IP 地址&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;IP 地址按照划分大小分为 IPv4 和 IPv6。&lt;/li&gt;
&lt;li&gt;IP 地址按照网络类型分为：公网 IP 和私网 IP。&lt;/li&gt;
&lt;li&gt;局域网内的 IP 地址是由路由器进行分配的。&lt;/li&gt;
&lt;li&gt;路由器的 IP 地址是由 ISP 动态分配的，也可能是静态分配的。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;局域网&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#局域网&#34;&gt;#&lt;/a&gt; 局域网&lt;/h2&gt;
&lt;p&gt;局域网在数据链路层通过以太网协议传输数据。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;局域网是一种计算机网络，通常覆盖的范围较小，局域网允许连接到网络上的设备（计算机打印机等）之间相互通信和共享资源，特点是传输速度快，延迟低。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;局域网除了以太网还有无线局域网、令牌环网等网络技术。&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;以太网&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#以太网&#34;&gt;#&lt;/a&gt; 以太网&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;以太网是一种局域网技术，定义了数据在局域网中的传输方式，以太网使用 MAC 地址进行设备间的通信，并且支持多种传输介质，包含双绞线、光纤等。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;以太网链路&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#以太网链路&#34;&gt;#&lt;/a&gt; 以太网链路&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;概念&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;以太网链路是指：在以太网技术中，两个网络设备之间的物理连接或逻辑连接。&lt;/li&gt;
&lt;li&gt;物理连接通过：双绞线、光纤等&lt;/li&gt;
&lt;li&gt;逻辑连接通过：交换机或路由器等设备&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;以太网协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#以太网协议&#34;&gt;#&lt;/a&gt; 以太网协议&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;以太网链路传输过程&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;封装成帧（帧头（包含目的地址和源 MAC 地址）、数据载荷（承载上层协议的数据）和帧尾（包含 CRC 循环冗余校验的字段，用于错误检测））&lt;/li&gt;
&lt;li&gt;访问控制（多个设备同时发送数据会导致冲突，以太网链路使用载波监听多路访问协议来控制设备的访问）&lt;/li&gt;
&lt;li&gt;传输（通过物理介质发送封装好的以太网帧）&lt;/li&gt;
&lt;li&gt;接收（网络接口卡捕获物理介质传输过来的比特流，将物理信号转换为电子信号）&lt;/li&gt;
&lt;li&gt;解封装（通过帧尾 CRC 字段确认是否存在错误，如果数据无误则将其传递给上层协议进一步处理）&lt;/li&gt;
&lt;li&gt;确认（全双工通信中，接收设备可能会发送一个确认信号回发送设备，告知数据成功接收）&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;集线器&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#集线器&#34;&gt;#&lt;/a&gt; 集线器&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;概念&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;一种基本的网络设备，用于将多个网络设备连接到一个单一的物理网络段，主要功能用于转发，但是由于各个端口之间不记录与设备间的映射关系，所以要以广播的方式转发、传输效率很低。&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;交换机&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#交换机&#34;&gt;#&lt;/a&gt; 交换机&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;概念&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;交换机是一种更高级的网络设备，记录了每个端口对应设备的 MAC 地址，进而实现针对性的转发。它可以通过：MAC 地址学习，帧转发和交换机端口来管理数据流。&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;MAC 地址学习&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;交换机能够学习并维护一个 MAC 地址表，记录每个端口上连接设备的 MAC 地址。&lt;/li&gt;
&lt;li&gt;帧转发：当交换机接收到一个帧数据流时，它会查看帧内的 MAC 地址，并根据 MAC 地址表决定将帧转发到哪一个端口，如果目的 MAC 地址不在表中，交换机会通过地址解析协议（广播所有端口）找到对应的 MAC 地址，并更新 MAC 地址表&lt;/li&gt;
&lt;li&gt;交换机端口：交换机每个端口可以独立工作在全双工模式，这意味着数据可以同时双向传输，提高了传输效率。&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;mac地址&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#mac地址&#34;&gt;#&lt;/a&gt; MAC 地址&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;每台设备都有自己唯一的 MAC 地址，出厂就已经指定了。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;地址解析协议arp&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#地址解析协议arp&#34;&gt;#&lt;/a&gt; 地址解析协议 ARP&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;地址解析协议 ARP 用于将 IP 地址解析到 MAC 地址，当通信发生在不同网络时，ARP 可以结合路由信息通过代理 ARP 或路由器的 ARP 表来解析目标 MAC 地址。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;网际报文控制协议icmp&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网际报文控制协议icmp&#34;&gt;#&lt;/a&gt; 网际报文控制协议 ICMP&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;ICMP 网际报文控制协议是 TCP/IP 协议族的一种网络层协议，是一个面向无连接的协议，不保证消息的可靠性只发送控制信息，用于在 IP 主机和路由器之间传递控制信息。&lt;br /&gt;
ICMP 和 UDP 的区别&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;UDP 工作在传输层，&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;内网穿透&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#内网穿透&#34;&gt;#&lt;/a&gt; 内网穿透&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;内网穿透的原因是因为内网 IP 是由路由器分配的，内网可以访问外网（公网），但是外网由于没有这个路由器上对应到该内网的端口映射关系，因此外网访问不到内网&lt;/li&gt;
&lt;li&gt;内网穿透的原理就是：内网的服务主动访问外网的某个服务器，主动被这个外网的服务器所代理。&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;分层&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#分层&#34;&gt;#&lt;/a&gt; 分层&lt;/h1&gt;
&lt;h2 id=&#34;应用层应用之间-传输数据&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#应用层应用之间-传输数据&#34;&gt;#&lt;/a&gt; 应用层（应用之间、传输数据）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;最上层的应用就是应用层&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;我们直接接触的就是应用层，电脑或手机使用的 &lt;code&gt;应用软件&lt;/code&gt; 就是在应用层实现&lt;/li&gt;
&lt;li&gt;应用层只需要专注于为用户提供应用功能，如: &lt;code&gt;HTTP&lt;/code&gt;   &lt;code&gt;FTP&lt;/code&gt;   &lt;code&gt;DNS&lt;/code&gt;  等&lt;/li&gt;
&lt;li&gt;应用层不用关系数据是如何传输的，应用层工作在操作系统中的用户态，传输层及以下工作在内核态&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;传输层主机之间-分段&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#传输层主机之间-分段&#34;&gt;#&lt;/a&gt; 传输层（主机之间、分段）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;传输层并不直接负责将数据从一个设备传到另一个设备，因为实际的网络传输环节是错综复杂的，中间有很多线路和选择，传输层的设计理念是简单、高效和专注，传输层只需要服务好应用即可.&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;传输层用于处理应用层的数据包，为应用层提供网络支持&lt;/li&gt;
&lt;li&gt;传输层有两个协议:  &lt;code&gt;TCP&lt;/code&gt;  和 &lt;code&gt;UDP&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;UDP (用户数据报协议)，是无连接的不可靠服务&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;UDP 只负责发送数据包，不保证数据包的可靠性，因此它的 &lt;code&gt;实时性更好&lt;/code&gt; ， &lt;code&gt;传输效率更高&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;TCP (传输控制协议)，面向连接的可靠服务&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;TCP 在传输数据之前，要先进行 &lt;code&gt;三次握手&lt;/code&gt; 建立连接， &lt;code&gt;最少三次握手才能保证接收方和发送方具有正常的收发能力&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;TCP 在断开连接时，要进行 &lt;code&gt;四次挥手&lt;/code&gt; 断开连接， &lt;code&gt;断开时，发送方会先发送数据，然后再发送一个断开的消息，这两次不能合并的原因就是：一旦接收方返回的数据包丢失，就会导致接收方认为连接断开，而发送方还要发送数据，从而导致半开连接的状态&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;TCP 相比于 UDP 多了:  &lt;code&gt;流量控制&lt;/code&gt; 、 &lt;code&gt;超时重传&lt;/code&gt; 、 &lt;code&gt;拥塞控制&lt;/code&gt; 等特性，目的是保证数据包能可靠的传输给对方&lt;/li&gt;
&lt;li&gt;当传输层的数据包大小超过 &lt;code&gt;TCP最大报文段&lt;/code&gt; 时，就要重新 &lt;code&gt;进行数据包分块&lt;/code&gt; ，这样即使中途有一个分块丢失了，也只需要重新发送这一个分块，而不必重新发送整个数据包。其中的每个分块被成为 &lt;code&gt;TCP段&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;设备作为接收方时，传输层要负责将数据包传给应用，但是一台设备上可能有很多应用在接收或者传输数据，因此需要一个编号进行区分，这个编号就是 &lt;code&gt;端口&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;传输层并不直接负责传输，他只负责处理好应用数据的传输功能，作为应用数据的传输媒介，实际的传输功能由下一层网络层来处理&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;网络层主机设备之间-分组-数据报&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网络层主机设备之间-分组-数据报&#34;&gt;#&lt;/a&gt; 网络层（主机设备之间、分组、数据报）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;网络层负责将数据从一个设备传输到另一个设备&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;网络层最常用的协议是 IP &lt;code&gt;协议&lt;/code&gt; ，用于得到一个发送到网络的 IP 报文&lt;/li&gt;
&lt;li&gt;IP 协议会将 &lt;code&gt;传输层的报文&lt;/code&gt; 作为 &lt;code&gt;数据部分&lt;/code&gt; ，再加上 &lt;code&gt;IP包头&lt;/code&gt; 组成 &lt;code&gt;IP报文&lt;/code&gt; ，如果 IP 报文大小超过 MTU, 就会再次进行分片，得到一个即将发送到网络的 IP 报文&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;ip 地址寻址 (选择方向)&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;由于设备太多，因此网络层需要有一个区分设备的编号，即 &lt;code&gt;ip地址&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;ip 地址通过子网掩码被分为两种意义: &lt;code&gt;网络号&lt;/code&gt; 和 &lt;code&gt;主机号&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;网络号&lt;/code&gt; 标识该 ip 地址属于哪个子网&lt;/li&gt;
&lt;li&gt;&lt;code&gt;主机号&lt;/code&gt; 标识同一子网下的不同主机&lt;/li&gt;
&lt;li&gt;区分 ip 地址时需要子网掩码才能计算出 ip 地址的网络号和主机号， &lt;code&gt;网络号 = IP地址 &amp;amp; 子网掩码&lt;/code&gt; ， &lt;code&gt;主机号 = IP地址 &amp;amp; ~子网掩码&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;ip 地址路由 (选择路径)&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;两台设备不是直接通过网线相连的，而是通过很多网关、路由器、交换机等多种网络连接起来的，从而形成了很多网络路径，当数据包到达一个网络节点，就需要通过路由算法决定下一步走哪一条路径&lt;/li&gt;
&lt;li&gt;ip 地址路由就是先找到目标地址的子网，再将数据包转发到对应的网络中&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;数据链路层以太网设备之间-封装成帧&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#数据链路层以太网设备之间-封装成帧&#34;&gt;#&lt;/a&gt; 数据链路层（以太网设备之间、封装成帧）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;在 IP 头部的前面加上 MAC 头部，并封装成数据帧发送到网络上&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;物理层物理媒介之间-物理信号变为电子信号&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#物理层物理媒介之间-物理信号变为电子信号&#34;&gt;#&lt;/a&gt; 物理层（物理媒介之间、物理信号变为电子信号）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;以太网&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;以太网就是一种在局域网内，将附近的设备连接起来，使他们之间可以进行通讯的技术&lt;/li&gt;
&lt;li&gt;常见的以太网有:  &lt;code&gt;wifi接口&lt;/code&gt;   &lt;code&gt;以太网交换机&lt;/code&gt;   &lt;code&gt;路由器以太网接口&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;MAC地址&lt;/code&gt; 用于标识以太网上的设备， &lt;code&gt;它和网络接口卡相绑定&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;以太网在判断网络包的目的地时，必须采用相匹配的方式才能在以太网中将包发往目的地，而 &lt;code&gt;MAC地址&lt;/code&gt; 就是这个作用&lt;/li&gt;
&lt;li&gt;通过 &lt;code&gt;ARP地址解析协议&lt;/code&gt; 就可以获得到 &lt;code&gt;MAC地址&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;无线局域网 WLAN&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;和以太网的工作大致相同，不同在于 &lt;code&gt;无线局域网使用无线电波进行数据传输&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;url输入网址后发生了什么&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#url输入网址后发生了什么&#34;&gt;#&lt;/a&gt; url 输入网址后，发生了什么&lt;/h1&gt;
&lt;ol&gt;
&lt;li&gt;补全 url&lt;/li&gt;
&lt;/ol&gt;
&lt;blockquote&gt;
&lt;p&gt;补全 url 协议、端口号和默认文件名，http 默认 80 端口，https 默认 443 端口，index.html&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;检查浏览器缓存&lt;/li&gt;
&lt;li&gt;生成 http 请求&lt;/li&gt;
&lt;li&gt;进行 DNS 解析&lt;br /&gt;
生成 http 请求之后，如果浏览器和本地 DNS 服务器中没有相应的缓存，就会通过本地 DNS 服务器进行请求，询问域名对应的 ip 地址。&lt;/li&gt;
&lt;/ol&gt;
&lt;blockquote&gt;
&lt;p&gt;DNS 用于查询域名对应的 ip 地址，在域名中，越靠右其层级越高，实际上域名末尾还有一个 . ，他表示根域名，.com 表示顶级域名，baidu 表示权威域名&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;跟域名（DNS）服务器（.）&lt;/li&gt;
&lt;li&gt;顶级域名（DNS）服务器（.com）&lt;/li&gt;
&lt;li&gt;权威域名（DNS）服务器（&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cDovL2RtcXdlYi5jb20=&#34;&gt;dmqweb.com&lt;/span&gt;）&lt;/li&gt;
&lt;li&gt;本地 DNS 服务器。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;5&#34;&gt;
&lt;li&gt;得到 IP 地址后，发生系统调用，交给 &lt;code&gt;操作系统网络协议栈&lt;/code&gt; ，找到其使用的协议为 &lt;code&gt;TCP协议&lt;/code&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;blockquote&gt;
&lt;p&gt;操作系统协议栈就是一组网络通信协议的集合，用于标准化通信，分层处理，模块化设计，网络管理和接口定义等。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ol start=&#34;6&#34;&gt;
&lt;li&gt;加上 TCP 首部封装为 TCP 报文（操作系统的 TCP 协议模块、传输层）&lt;/li&gt;
&lt;li&gt;加上 IP 首部封装为 IP 数据报（操作系统 IP 协议模块、网络层）&lt;/li&gt;
&lt;li&gt;加上 MAC 地址帧头帧尾，封装为网络包（将 IP 数据包封装成网络帧、数据链路层）&lt;/li&gt;
&lt;li&gt;交给网卡，网卡驱动程序将网络包转为电信号，通过网线发送出去&lt;/li&gt;
&lt;li&gt;网络包被交换机和路由器中转，最后被转发到目的 ip 地址对应的路由器&lt;/li&gt;
&lt;li&gt;路由器根据 IP 地址找到 MAC 地址对应的设备&lt;/li&gt;
&lt;li&gt;设备（服务器）通过端口号找到对应的服务&lt;/li&gt;
&lt;li&gt;服务端处理请求的数据，通过相同的方式，返回 html 给请求方的浏览器&lt;/li&gt;
&lt;li&gt;浏览器解析 html 为 DOM 树，解析 css 为 CSSOM 树，两者不冲突，当遇到 js 文件就会去请求并执行 js 文件，js 文件由于会操作 DOM 树，因此和渲染主线程互斥。&lt;/li&gt;
&lt;li&gt;将 DOM 树和 CSSOM 树合并为渲染树。&lt;/li&gt;
&lt;li&gt;浏览器进行分层、布局、光栅化生成绘制指令。&lt;/li&gt;
&lt;li&gt;最后调用 GPU 渲染像素点。&lt;/li&gt;
&lt;/ol&gt;
&lt;h1 id=&#34;http&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#http&#34;&gt;#&lt;/a&gt; HTTP&lt;/h1&gt;
&lt;h2 id=&#34;概念-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#概念-2&#34;&gt;#&lt;/a&gt; 概念&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;超文本传输协议，计算机世界里专门在「两点」之间「传输」文字、图片、音频、视频等「超文本」数据的「约定和规范」。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;常见状态码&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#常见状态码&#34;&gt;#&lt;/a&gt; 常见状态码&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;1xx 提示信息，表示协议处理的中间状态&lt;br /&gt;
 2xx 成功&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;200 OK&lt;/li&gt;
&lt;li&gt;204 无内容&lt;/li&gt;
&lt;li&gt;206 分块下载或断点上传&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;3xx 资源变动&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;301 永久重定向&lt;/li&gt;
&lt;li&gt;302 临时重定向&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;4xx 请求有误&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;400 请求有误（笼统）&lt;/li&gt;
&lt;li&gt;403 禁止访问&lt;/li&gt;
&lt;li&gt;404 未找到资源&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;5xx 服务器错误&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;500 服务器错误（笼统）&lt;/li&gt;
&lt;li&gt;501 不支持该请求&lt;/li&gt;
&lt;li&gt;502 网关或代理错误&lt;/li&gt;
&lt;li&gt;503 服务器繁忙&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;http字段&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#http字段&#34;&gt;#&lt;/a&gt; HTTP 字段&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Host，指定服务器域名&lt;/li&gt;
&lt;li&gt;Content-Length 数据长度&lt;/li&gt;
&lt;li&gt;Connection 连接机制&lt;/li&gt;
&lt;li&gt;Content-Type 数据类型&lt;/li&gt;
&lt;li&gt;Content-Encoding、Accept-Encoding 压缩方法&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;http缓存&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#http缓存&#34;&gt;#&lt;/a&gt; HTTP 缓存&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;强制缓存，用于长时间不会变化的资源&lt;br /&gt;
通过资源的 Cache-Control（资源有效期）响应头和 Expires（缓存到期时间）字段来判断资源是否过期，如果资源没有过期，浏览器直接使用缓存的资源，而不发送网络请求。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;Cache-Control 优先级大于 Expires。&lt;/li&gt;
&lt;li&gt;最开始使用 Expires 表示资源的过期时间，但是由于客户端和服务器端时间可能不一致，从而导致一些问题&lt;/li&gt;
&lt;li&gt;后来出现 Cache-control 表示资源的过期时长。&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;协商缓存，用于不定时变化，但不会经常变化的资源&lt;br /&gt;
浏览器正常发送网络请求，服务端通过请求头判断是否要返回 304 状态码，表示浏览器可以使用本地缓存的资源。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;Etag 优先级大于 Last-Modified。&lt;/li&gt;
&lt;li&gt;最开始使用 Last-Modified（资源最后修改时间）和 If-Modified-Since（上一次从服务器获取的 Last-Modified 值），但是 last-Modified 是以秒级别记录的，当资源在一秒内发生改变的话，last-modified 是无感知的。&lt;/li&gt;
&lt;li&gt;后面使用 Etag（资源唯一标识）和 If-None-Match（上一次从服务器获取的 Etag），比对服务器的 Etag，如果比对相同就返回 304 状态码。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;https和http的不同&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#https和http的不同&#34;&gt;#&lt;/a&gt; HTTPS 和 HTTP 的不同&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;HTTPS 就是在 HTTP 的基础之上，进行了 TLS 加密（前身是 SSL），进行信息加密和身份验证。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;SSL 证书，就是保存在服务器的证书文件，服务端需要向 CA 证书授权中心申请&lt;/li&gt;
&lt;li&gt;SSL 加密过程先通过非对称加密获取密钥，然后通过对称加密进行通信，从而避免了非对称加密繁琐的过程&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;具体加密的过程就是：&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;客户端发送自己支持的加密方式，并给出第一随机数&lt;/li&gt;
&lt;li&gt;服务端发送自己的加密方式、证书、并给出第二随机数&lt;/li&gt;
&lt;li&gt;客户端根据两个随机数随机生成预主密钥，通过证书中的公钥对预主密钥进行加密，发送给服务端&lt;/li&gt;
&lt;li&gt;服务端通过私钥对加密的预主密钥进行解密，获取到预主密钥&lt;/li&gt;
&lt;li&gt;双方通过第一随机数、第二随机数和预主密钥混合，得到会话密钥，双方的相同&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;对称加密的过程就是：&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;后续双方都使用会话密钥进行加密，会话密钥只在当前会话中有效。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;http版本&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#http版本&#34;&gt;#&lt;/a&gt; HTTP 版本&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;HTTP1.1&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;核心：pipeline 管道模式，请求到一个之后才能去请求下一个，其中有一个没有收到就会导致后面的都接收不到，从而导致 HTTP 队头阻塞&lt;/li&gt;
&lt;li&gt;持久连接，保持连接状态，每个域有最大的持久连接数（HTTP 队头阻塞）：chrome 为 6 个，其他浏览器各不相同（减少请求次数：域名分片、精灵图和 base64 图片）&lt;/li&gt;
&lt;li&gt;首部重复发送（尤其是 cookie）&lt;/li&gt;
&lt;li&gt;明文传输，报文进行压缩，但是首部不压缩&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;HTTP2&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;多路复用（用于解决 HTTP 队头阻塞问题，但没有解决 TCP 层面的队头阻塞问题，由于 TCP 数据包中没有数据帧，为了可靠性需要需要等到全部的数据包响应完成）&lt;/li&gt;
&lt;li&gt;头部压缩，多个请求相同时，会帮助消除重复的部分。&lt;/li&gt;
&lt;li&gt;服务器推送（将浏览器需要的文件提前发送）&lt;/li&gt;
&lt;li&gt;报文变为二进制的帧格式，增加了传输效率&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;HTTP3&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;基于 UDP 协议和 TLS 构建出 QUIC 协议，没有 TCP 的三次握手，解决了 TCP 队头阻塞的问题，QUIC 帧中就有数据帧，解决了 TCP 层面的队头阻塞的问题，实现多路复用&lt;/li&gt;
&lt;li&gt;具体解决方式是使用: &lt;code&gt;流帧&lt;/code&gt; ，QUIC 的流帧分别跟踪每个流的字节范围，当一个 QUIC 数据包丢失时，只有属于那个特定流的数据会被阻塞，其他流可以正常处理&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;ipv4和ipv6&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ipv4和ipv6&#34;&gt;#&lt;/a&gt; ipv4 和 ipv6&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;ipv4 使用 4 个字节，大小有限不够使用了，所以有了 ipv6,ipv6 使用 16 个字节&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;图解网络&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#图解网络&#34;&gt;#&lt;/a&gt; 图解网络&lt;/h1&gt;

 &lt;h1 id=&#34;js&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#js&#34;&gt;#&lt;/a&gt; JS&lt;/h1&gt;
&lt;h2 id=&#34;map和对象区别&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#map和对象区别&#34;&gt;#&lt;/a&gt; map 和对象区别&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;声明方式不同&lt;/li&gt;
&lt;li&gt;对象的键只能是 symbol 和字符串，map 的键可以是任意类型&lt;/li&gt;
&lt;li&gt;对象的属性有排序顺序 (排序为索引属性和命名属性),map 中 key 的顺序就是插入的顺序&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;遮蔽&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#遮蔽&#34;&gt;#&lt;/a&gt; 遮蔽&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;js 中重复定义变量，导致新定义的同名变量覆盖原变量的过程就是遮蔽&lt;/li&gt;
&lt;li&gt;var 和 function 关键字定义的变量会发生遮蔽&lt;/li&gt;
&lt;li&gt;js 中函数的变量名是只读的，不能被修改&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;void-0-替代undefined&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#void-0-替代undefined&#34;&gt;#&lt;/a&gt; void 0 替代 undefined&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;undefined 不同于 null,null 不可以被重新赋值，但是 undefined 可以被重新赋值，因此不可靠&lt;/li&gt;
&lt;li&gt;void 0 会稳定返回 undefined, 比直接使用 undefined 更加可靠&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;定时器4ms延迟&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#定时器4ms延迟&#34;&gt;#&lt;/a&gt; 定时器 4ms 延迟&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;定时器 settimeout 和 setInterval 当嵌套层级达到 5 层时，会有 4ms 最小延迟时间，原因在于如果定时器一直 0ms 嵌套，就会导致 js 引擎过渡循环，从而使得时间循环被阻塞&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;promise对象的执行器函数&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#promise对象的执行器函数&#34;&gt;#&lt;/a&gt; Promise 对象的执行器函数&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Promise 对象在被创建时，会立即同步执行其执行器函数&lt;/li&gt;
&lt;li&gt;Promise 对象被 resolve 时，会在微任务队列中添加.then 方法注册的回调函数&lt;/li&gt;
&lt;li&gt;Promise 对象被 reject 时，会在微任务队列中添加.catch 方法注册的回调函数&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;promise&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#promise&#34;&gt;#&lt;/a&gt; Promise&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;promise 可以多次添加.then 方法，并获取到上一个.then 方法的返回值&lt;/li&gt;
&lt;li&gt;.then 方法第一个参数是成功回调，第二个参数是失败回调，.catch 方法是.then 方法的封装（不使用第一个参数）&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;promiseresolve&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#promiseresolve&#34;&gt;#&lt;/a&gt; Promise.resolve&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;传入 promise 时，Promise.resolve &lt;code&gt;返回原来的promise实例&lt;/code&gt; ，此时.then 相当于链式调用.then 方法&lt;/li&gt;
&lt;li&gt;传入静态值时，Promise.resolve 会将值封装为 resolve 状态的 promise， &lt;code&gt;返回值是新生成的Promise实例&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;基本包装类型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基本包装类型&#34;&gt;#&lt;/a&gt; 基本包装类型&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;js 为了便于基本类型操作，提供了 3 个特殊的引用类型：Boolean、Number 和 String, 具有基本类型的特殊行为，可以创建基本包装类型 (字面量或普通函数调用)&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; str &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;字符串&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; str1 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; str&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;substring&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;// 调用方法时，创建了基本包装类型&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;ul&gt;
&lt;li&gt;当读取一个基本类型时，js 会在栈中自动创建基本类型，当对基本数据类型使用一些方法的时候，js 引擎会自动创建一个临时的包装对象，使我们可以调用一些方法，这个临时对象存活的时间很短，操作完成后就会被销毁&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;let&lt;/span&gt; str &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;蛙人&#39;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;str&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;age &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;23&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;// 创建基本包装类型，但是调用后立即被销毁了&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;str&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;age&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;// undefined&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;ul&gt;
&lt;li&gt;通过 new 调用时，创建的是引用数据类型，两者的区别就在于：基本包装类型调用完之后立即被销毁&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;css&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#css&#34;&gt;#&lt;/a&gt; CSS&lt;/h1&gt;
&lt;h2 id=&#34;行内元素行盒&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#行内元素行盒&#34;&gt;#&lt;/a&gt; 行内元素（行盒）&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;a span strong em i b u mark sub sup code label summary sup&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;块级元素块盒&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#块级元素块盒&#34;&gt;#&lt;/a&gt; 块级元素（块盒）&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;div ul li table dl dt ddd p h1-h6 details dialog&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;行内块元素行块盒&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#行内块元素行块盒&#34;&gt;#&lt;/a&gt; 行内块元素（行块盒）&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;button input img select textarea&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;块盒布局规则&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#块盒布局规则&#34;&gt;#&lt;/a&gt; 块盒布局规则&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;水平盛满父元素&lt;/li&gt;
&lt;li&gt;垂直方向相邻元素和父子级关系的 margin 合并&lt;/li&gt;
&lt;li&gt;父子关系 margin 合并塌陷，父元素无视浮动的子元素&lt;/li&gt;
&lt;li&gt;正常元素会被同级浮动元素所覆盖&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;display的值&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#display的值&#34;&gt;#&lt;/a&gt; display 的值&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;none block inline inline-block flex inline-flex grid inline-grid table inherit unset revert&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;bfc解决了什么问题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bfc解决了什么问题&#34;&gt;#&lt;/a&gt; BFC 解决了什么问题&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;开启 BFC 之后，其子元素不会再产生 margin 塌陷的问题，不会无视浮动的子元素，自己不会被其他浮动元素所覆盖&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;如何开启bfc&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#如何开启bfc&#34;&gt;#&lt;/a&gt; 如何开启 BFC&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;float 属性&lt;/li&gt;
&lt;li&gt;position 属性不是 relative&lt;/li&gt;
&lt;li&gt;overflow 属性不是 visible&lt;/li&gt;
&lt;li&gt;display 不是 none&lt;/li&gt;
&lt;li&gt;父元素设置 flex (flex 的伸缩项目)&lt;/li&gt;
&lt;li&gt;多列容器（column-count 属性）&lt;/li&gt;
&lt;li&gt;根元素 HTML&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;水平垂直居中&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#水平垂直居中&#34;&gt;#&lt;/a&gt; 水平垂直居中&lt;/h2&gt;
&lt;p&gt;&lt;code&gt;子元素高度未知&lt;/code&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;父元素设置 display:flex 或 grid, 子元素设置 margin:auto&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;由于垂直方向上块级盒子存在 margin 合并的布局特性，因此垂直居中的 margin:auto 无效，可以将父元素 display:flex 或者 grid。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;flex 布局&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;justify-content:center 和 align-items:center&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;grid 布局&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;place-items:center 直接居中，justify-content:center 水平居中、align-content:center 垂直居中&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;absolute + transform&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;position:absolute 然后 transform:translateY (-50%)&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;absolute + calc&lt;br /&gt;
 &lt;code&gt;子元素高度已知&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;absolute + 负 margin&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;css画三角形&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#css画三角形&#34;&gt;#&lt;/a&gt; css 画三角形&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;宽高设为 0，border 只有一处不透明&lt;/li&gt;
&lt;li&gt;clip-path:polygon(0 0,0% 100%,100%,50%)&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;css可继承的属性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#css可继承的属性&#34;&gt;#&lt;/a&gt; CSS 可继承的属性&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;visibility&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;visibility 属性是继承而来的，父元素如果设置了 visibility, 子元素也会继承该属性&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;文本相关&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;color、font、letter-spacing、line-height、text-align、text-shadow、text-transform、white-space、word-spacing、direction、unicode-bidi&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;用户界面状态相关的伪类&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;:hover、:active、:focus 等，他们可以继承用户界面属性&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;vue&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#vue&#34;&gt;#&lt;/a&gt; Vue&lt;/h1&gt;
&lt;h2 id=&#34;vue2和vue3有什么不同&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#vue2和vue3有什么不同&#34;&gt;#&lt;/a&gt; Vue2 和 Vue3 有什么不同&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;响应式原理不同&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;vue2 使用 Object.defineProperty 拦截对象对应属性的 getter 和 setter，而 vue3 使用 Proxy 代理整个对象&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;vue3 为组合式 api,vue2 为 options api&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;vue3 借鉴 react 抛弃面向对象的编程方式，采用函数式编程的架构方式，函数式编程的规范使得状态可以被集中式管理，具有更加清晰的状态转义逻辑。此外减小了心智负担，因为 options api 中组件逻辑和状态相分离，组件过大时不利于编写&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;生命周期钩子不同&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;vue3 摒弃 create 两个钩子，采用 setup 语法糖进行替代，因为没什么用，增加了 fragements&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;react&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#react&#34;&gt;#&lt;/a&gt; React&lt;/h1&gt;
&lt;h1 id=&#34;操作系统&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#操作系统&#34;&gt;#&lt;/a&gt; 操作系统&lt;/h1&gt;
&lt;h1 id=&#34;网络&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网络&#34;&gt;#&lt;/a&gt; 网络&lt;/h1&gt;
&lt;h1 id=&#34;html&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#html&#34;&gt;#&lt;/a&gt; HTML&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;script 标签请求&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;浏览器解析 html 文档时，遇到 script 标签会停止解析，转而先执行或下载 script 标签中的 JavaScript 代码或外部文件，意味着脚本在下载和执行完成之前，页面的解析和渲染过程会被阻塞&lt;/li&gt;
&lt;li&gt;defer 脚本和 async 脚本都可以异步下载外部文件&lt;/li&gt;
&lt;li&gt;async 脚本加载完之后立即执行，而 defer 脚本需要等到 DOMContentLoaded 之后才执行&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;src 和 href 的区别&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;href 表示超文本引用，href 是指与该页面有关联的内容，在 link 和 a 元素上使用&lt;/li&gt;
&lt;li&gt;src 表示资源的来源地址，在 img、script 和 iframe 等元素上&lt;/li&gt;
&lt;li&gt;可替换的元素上 (img 标签) 使用 src 属性，src 属性仅仅嵌入当前资源到当前文档元素定义的位置，href 用于在涉及的文档和外部资源之间建立一个关系&lt;/li&gt;
&lt;li&gt;请求 src 资源时，会将资源下载并应用到文档内，当浏览器解析到该元素时，会暂停其他资源的下载和处理，直到将该资源加载和执行完毕，而解析 href 资源时，会下载并且不会停止对当前文档的处理&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;iframe&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;iframe 标签是一个内联框架 (inline-block 元素), 就是用来在当前 HTML 页面中嵌入另一个文档的，并且所有主流浏览器都支持 iframe 标签&lt;/li&gt;
&lt;li&gt;优点&lt;/li&gt;
&lt;li&gt;
&lt;ul&gt;
&lt;li&gt;原样嵌入网页内容&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;ul&gt;
&lt;li&gt;更换快捷&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;ul&gt;
&lt;li&gt;代码可重用&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;缺点&lt;/li&gt;
&lt;li&gt;
&lt;ul&gt;
&lt;li&gt;不易管理、滚动条和样式难看、设备兼容性差、会增加 http 请求&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;ul&gt;
&lt;li&gt;iframe 的 src 不设置为 about:blank 的话，即使使用 clear 方法内存也不会释放掉&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;

 &lt;h1 id=&#34;介绍&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#介绍&#34;&gt;#&lt;/a&gt; 介绍&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;rollup 是一个 ES 模块化打包工具，可以帮助我们编译小的代码到一个大的、负责的代码中，比如一个库或者一个应用程序&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h1 id=&#34;对比&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#对比&#34;&gt;#&lt;/a&gt; 对比&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;我们会发现 Rollup 的定义、定位和 webpack 非常的相似：&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;Rollup 也是一个模块化的打包工具，但是 Rollup 主要是针对 ES Modulej 进行打包的；&lt;/li&gt;
&lt;li&gt;另外 webpacki 通常可以通过各种 loader 处理各种各样的文件，以及处理它们的依赖关系；&lt;/li&gt;
&lt;li&gt;rollup 更多时候是专注于处理 JavaScript 代码的（当然也可以处理 css、font、vue 等文件&lt;/li&gt;
&lt;li&gt;另外 rollup 的配置和理念相对于 webpack 来说，更加的简洁和容易理解；&lt;/li&gt;
&lt;li&gt;在早期 webpack 不支持 tree shaking 时，rollup. 具备更强的优势：&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;目前 webpack 和 rollup 分别应用在什么场景呢？&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;通常在实际项目开发过程中，我们都会使用 webpack (比如 vue、react、angularI 项目都是基于 webpack 的)&lt;/li&gt;
&lt;li&gt;在对库文件进行打包时，我们通常会使用 rollup (比如 vue、react、.dayjs 源码本身都是基于 rollupl 的)；&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;优点&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#优点&#34;&gt;#&lt;/a&gt; 优点&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;rollup 开发 JavaScript 库文件时，通常使用 rollup 进行打包构建&lt;/li&gt;
&lt;li&gt;rollup 的优势在于：配置少，输出纯净，没有多余复杂的配置和功能&lt;/li&gt;
&lt;li&gt;rollup 可以创建更小的 bundle，从而提升页面的加载速度，优化性能&lt;/li&gt;
&lt;li&gt;rollup 具有良好的兼容性，尽管 rollup 原生支持 ES 模块，但是通过配置也可以生成 CommonJS、IIFE、UMD 和 AMD 等模块&lt;/li&gt;
&lt;li&gt;rollup 可以很方便的打包各种模块化规范（iife、es、amd、umd 等）&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;安装&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装&#34;&gt;#&lt;/a&gt; 安装&lt;/h1&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;figcaption data-lang=&#34;bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;npm&lt;/span&gt; i &lt;span class=&#34;token parameter variable&#34;&gt;-g&lt;/span&gt; rollup&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h1 id=&#34;命令&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#命令&#34;&gt;#&lt;/a&gt; 命令&lt;/h1&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;figcaption data-lang=&#34;bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;rollup &lt;span class=&#34;token parameter variable&#34;&gt;--init&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;# 生成配置文件&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;rollup src/main.js &lt;span class=&#34;token parameter variable&#34;&gt;--config&lt;/span&gt; rollup.config.js &lt;span class=&#34;token comment&#34;&gt;# 使用 rollup.config.js 打包 main.js 文件&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;rollup src/main.js &lt;span class=&#34;token parameter variable&#34;&gt;--config&lt;/span&gt; rollup.config.js &lt;span class=&#34;token parameter variable&#34;&gt;--watch&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;# --watch 热启动打包&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;rollup src/main.js &lt;span class=&#34;token parameter variable&#34;&gt;--config&lt;/span&gt; rollup.config.js &lt;span class=&#34;token parameter variable&#34;&gt;--output&lt;/span&gt; dist/bundle.js &lt;span class=&#34;token comment&#34;&gt;#指定输出文件名称&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h1 id=&#34;rollupconfigjs&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#rollupconfigjs&#34;&gt;#&lt;/a&gt; rollup.config.js&lt;/h1&gt;
&lt;figure class=&#34;highlight js&#34;&gt;&lt;figcaption data-lang=&#34;JavaScript&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;const&lt;/span&gt; commonjs &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;require&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;@rollup/plugin-commonjs&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;// 需要进行安装&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;const&lt;/span&gt; resolve &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;require&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;@rollup/plugin-node-resolve&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;const&lt;/span&gt; babel &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;require&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;@babel/core&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;export&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;default&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp